IF OBJECT_ID('ssis_flow.Delta_ProductCategory') IS NULL SELECT TOP(0) NULLIF(R.[ProductCategoryID],R.[ProductCategoryID]) AS [ProductCategoryID],NULLIF(R.[Name],R.[Name]) AS [Name],NULLIF(R.[rowguid],R.[rowguid]) AS [rowguid],NULLIF(R.[ModifiedDate],R.[ModifiedDate]) AS [ModifiedDate],CONVERT(nvarchar(1),NULL) FlowOperation,CONVERT(bigint,NULL) FlowVersion,CONVERT(bigint,NULL) FlowBatchId INTO ssis_flow.Delta_ProductCategory FROM etl_raw.[ProductCategory] R;
