IF OBJECT_ID('ssis_flow.Delta_WorkOrder') IS NULL SELECT TOP(0) NULLIF(R.[WorkOrderID],R.[WorkOrderID]) AS [WorkOrderID],NULLIF(R.[ProductID],R.[ProductID]) AS [ProductID],NULLIF(R.[OrderQty],R.[OrderQty]) AS [OrderQty],NULLIF(R.[StockedQty],R.[StockedQty]) AS [StockedQty],NULLIF(R.[ScrappedQty],R.[ScrappedQty]) AS [ScrappedQty],NULLIF(R.[StartDate],R.[StartDate]) AS [StartDate],NULLIF(R.[EndDate],R.[EndDate]) AS [EndDate],NULLIF(R.[DueDate],R.[DueDate]) AS [DueDate],NULLIF(R.[ScrapReasonID],R.[ScrapReasonID]) AS [ScrapReasonID],NULLIF(R.[ModifiedDate],R.[ModifiedDate]) AS [ModifiedDate],CONVERT(nvarchar(1),NULL) FlowOperation,CONVERT(bigint,NULL) FlowVersion,CONVERT(bigint,NULL) FlowBatchId INTO ssis_flow.Delta_WorkOrder FROM etl_raw.[WorkOrder] R;
IF OBJECT_ID('ssis_flow.Delta_WorkOrderRouting') IS NULL SELECT TOP(0) NULLIF(R.[WorkOrderID],R.[WorkOrderID]) AS [WorkOrderID],NULLIF(R.[ProductID],R.[ProductID]) AS [ProductID],NULLIF(R.[OperationSequence],R.[OperationSequence]) AS [OperationSequence],NULLIF(R.[LocationID],R.[LocationID]) AS [LocationID],NULLIF(R.[ScheduledStartDate],R.[ScheduledStartDate]) AS [ScheduledStartDate],NULLIF(R.[ScheduledEndDate],R.[ScheduledEndDate]) AS [ScheduledEndDate],NULLIF(R.[ActualStartDate],R.[ActualStartDate]) AS [ActualStartDate],NULLIF(R.[ActualEndDate],R.[ActualEndDate]) AS [ActualEndDate],NULLIF(R.[ActualResourceHrs],R.[ActualResourceHrs]) AS [ActualResourceHrs],NULLIF(R.[PlannedCost],R.[PlannedCost]) AS [PlannedCost],NULLIF(R.[ActualCost],R.[ActualCost]) AS [ActualCost],NULLIF(R.[ModifiedDate],R.[ModifiedDate]) AS [ModifiedDate],CONVERT(nvarchar(1),NULL) FlowOperation,CONVERT(bigint,NULL) FlowVersion,CONVERT(bigint,NULL) FlowBatchId INTO ssis_flow.Delta_WorkOrderRouting FROM etl_raw.[WorkOrderRouting] R;
